/* Guided inquiry, item-level explanations, independent exit assessments and
   printable learning records. Everything is browser-local and fictional. */
const learningDate=()=>new Date().toLocaleString('zh-TW',{timeZone:'Asia/Taipei',hour12:false});
const lessonFor=e=>{const l=TPLessons[e.id];return l&&{...l,quiz:l.quiz.filter(q=>q.type==='choice'),worked:l.quiz.filter(q=>q.type==='number')}};
const practiceReasons={idle:['400 已由正常製造服務取得，I-05 要求避免再收同一報酬。','1,200 是 CAP-17 可驗證固定閒置，且同一補償尚未支付。','QA-09 由當地設定錯誤造成；不在本例總部取消補償範圍。'],recipe:['200 對應導入服務，與 K3 使用權是不同交易。','300 對應同一使用權，應從應有 1,800 扣掉。','1,800 是本案可靠方法結果，不是全部公司利潤或人數公式。'],synergy:['300 有談判工作與常規對價支持，不能全部否准。','500 只有成員身分請款，本例未支持額外服務對價。','700 同一折扣已在進貨價反映，缺乏再收的獨立依據。'],market:['法律登記是起點，需合併實際貢獻與權利分析。','500 包括本例全部形式的已有利益，不能忽略而重付。','額外部分是可靠總報酬 1,100 與已有 500 的差額，不等於廣告費或全球品牌利潤。'],distributor:['本例 SG 對特定市場風險的控制、資力與約定一致；還須扣已付 200。','倉儲 300 與信用 200 有 NL 實際權限與能力支持，不能跟著市場風險移走。','200 已是同一跌價補償，尚差只有 600 − 200。'],location:['600 已透過降價轉給外部客戶，集團內沒有這筆錢可分。','當地可比對象處在同一個人力市場，利潤率已反映當地成本，不需另做區位節省調整。','查核準則規定落在常規交易範圍外時，以中位數調整；不是調到區間邊緣。'],lowvalue:['TW 有工單與每月薪資紀錄證明受益，服務屬支援性質，且有可靠分析支持 5%。','銷售與行銷活動不適用簡化法，但改用一般分析後仍支持 315；標錯分類不等於全部否准。','董事會與投資人關係是為股東管理投資，TW 沒有取得獨立企業願意付費的利益。'],cca:['既有貢獻不能假設等於成本或零，要按價值衡量。','預期利益份額依簽約時合理預測的利益；研發人數是投入，不是利益。','參與人要能控制所承擔的風險並有資力；SG 的指導委員會實際核定且有資力。'],htvi:['試產洽談在移轉前已知，按當時評估的機率納入，是事前定價應考慮的資訊。','火災發生在移轉後且無法預見，不應據以調整。','差異超過 20%，又沒有雙邊預先訂價協議或五年商業化期間的豁免；但調整仍以事前可得資訊為準。'],'sandwich-history':['應以實際權利金交易及可靠費用分析判斷，不能用路經國名代替。','居住者、扣繳、協定與反濫用有不同年度及法源，不在這筆 TP 差額內。','可靠支持的 200 要保留，本例只調未支持的 800。'],treaty:['240 是第一案已固定的臺灣新增稅，不是罰鍰或因申請 MAP 自動撤銷。','180 是主管機關已確認範圍的減稅，既不能放大為 240，也不能忽略。','300 是待解決所得範圍；既非已減稅，也非永久無救濟。']};
function refsForStep(e,s){const own=lessonFor(e).refs;return [...new Set(s.kind==='costBase'?['cost','method']:s.kind==='profitSplit'?['split','method']:s.kind==='assetScope'?['restructure','intangible']:s.kind==='sequence'?['intangible','dempe']:s.kind==='document'?['contract',...own.slice(0,2)]:s.kind==='talk'&&own.includes('control')?['control','capacity',own[0]]:s.kind==='verdict'?['method',...own.slice(0,2)]:own.slice(0,3))]}
function ruleCards(keys){return [...new Set(keys)].map(key=>{const q=TPRules[key];return q?`<details class="learning-rule"><summary>OECD TPG 2022 ${q.ref} · ${q.title}</summary><dl><dt>規範意旨 · 教學摘要</dt><dd>${q.intent}</dd><dt>如何落地查核</dt><dd>${q.ask}</dd><dt>不能直接推出</dt><dd>${q.limit}</dd></dl><a href="${TP_PDF}#page=${q.page}" target="_blank" rel="noopener">對照 OECD 2022 英文原文 ${q.ref}（官方 PDF 第 ${q.page} 頁${q.print?'，印刷頁 '+q.print:''}）↗</a></details>`:''}).join('')}
function detailedRowsHTML(rows){return rows.map((x,k)=>`<article class="answer-analysis ${x.ok?'answer-right':'answer-wrong'}"><div><span>${x.ok?'✓':'✕'} 第 ${k+1} 項</span><b>${safe(x.label)}</b></div><dl><dt>你的作答</dt><dd>${safe(x.actual)}</dd><dt>正確答案／較可靠問法</dt><dd>${safe(x.expected)}</dd><dt>${x.ok?'為何成立':'錯在哪裡、為何要改'}</dt><dd>${safe(x.why)}</dd></dl></article>`).join('')}
function explanationHTML(e,s,rows){const wrong=rows.map((x,k)=>x.ok?null:k+1).filter(Boolean);return `<section class="learning-feedback"><div class="learning-feedback-head"><small>逐項解析 · 教學練習不計評量分數</small><h3>${wrong.length?`第 ${wrong.join('、')} 項需要修正`:'這次作答的證據與理由'}</h3></div>${detailedRowsHTML(rows)}<div class="fact-to-rule"><b>本案如何從事實走到規範</b><p>${safe(wrong.length?lessonFor(e).reasoning[0]:(s.insight||lessonFor(e).reasoning[0]))}</p></div>${ruleCards(refsForStep(e,s))}<p class="learning-footnote">TPG 是國際指引，並非直接核定的國內法條。上列為教學解說，原文請依段號對照。</p></section>`}
function appendExplanation(e,s,rows,r,step){const entry={kind:s.kind,label:s.label,step,rows,at:learningDate()};r.practiceLog??=[];r.practiceLog.push(entry);r.learningFeedback??={};r.learningFeedback[step]=entry;saveSeason();document.querySelector('#case-feedback .learning-feedback')?.remove();const html=explanationHTML(e,s,rows),next=$('#next-story-step');if(next)next.insertAdjacentHTML('beforebegin',html);else $('#case-feedback')?.insertAdjacentHTML('beforeend',html)}
function requestFailure(text,e){if(/私人|所有年度|整個硬碟|整個硬盤|所有.*帳簿/.test(text))return '這個範圍過大，沒有先限縮交易、期間及待證事項；私人訊息或全部年度資料不能只因集團關係就一概調取。';if(/只/.test(text))return `這個範圍過窄：單一形式文件或總數，不能同時回答本案的實際功能、風險控制、資力及金額。要查的是：${e.question}`;if(/全部|一律|直接|加總|不需|不必/.test(text))return '這個選項在取得必要資料以前，就先決定全部接受、全部否准或計算方式；跳過了實際交易、反證及方法可靠性的查證。';return `資料未完整對應本案待證事項：${e.question}。要把具體決策、權利、風險與帳目連起來，不能只收一種背景資料。`}
function practiceRows(e,r,s,button){const val=selector=>$(selector)?.value??'';const marked=selector=>!!$(selector)?.checked;
 if(['inspect','request','document'].includes(s.kind)){const options=s.kind==='document'?getFile(e,s.file).lines:s.options,k=Number(button.dataset.storyChoice??button.dataset.storyClause??button.dataset.storyRequest);return [TPLearning.row(s.prompt||s.title,options[k],options[s.correct],k===s.correct?`成立條件：${s.insight} ${lessonFor(e).reasoning[0]}`:`${s.missteps?.[k]||(s.kind==='request'?requestFailure(options[k],e):'這個條款未直接對應所問的特定權利與責任，需看正確條款並核對實際履行。')} 正確方向：${lessonFor(e).reasoning[0]}`)]}
 if(s.kind==='puzzle')return s.rows.map((row,k)=>{const a=val(`[data-puzzle-answer="${k}"]`);return TPLearning.row(row.label,a===''?'未作答':row.options[+a],row.options[row.correct],practiceReasons[e.id]?.[k]||s.insight)});
 if(s.kind==='sequence')return s.correct.map((answer,k)=>{const a=val(`[data-sequence-answer="${k}"]`);return TPLearning.row(`時間線位置 ${k+1}`,a===''?'未作答':s.items[+a],s.items[answer],`第 ${k+1} 步應為「${s.items[answer]}」。完整順序為 ${s.correct.map(j=>s.items[j]).join(' → ')}。${s.file?s.file+' 的日期支持這條線；':''}${s.insight}`)});
 if(s.kind==='profitSplit')return [TPLearning.numericRow('可分割剩餘利潤',val('#split-residual'),2500,'3,000 先扣 JP 200 與 SG 300，剩 2,500；不是把全部利潤直接乘因子。'),TPLearning.numericRow('JP 例行加剩餘的應有報酬',val('#split-jp-total'),1200,'JP 例行 200 + 剩餘 2,500 × 本案 40% = 1,200。已報 200 要在最後所得差額再扣除。')];
 if(s.kind==='costBase')return [['engineering','工程及現場成本 6,000',true,'本案服務活動相關成本，應依一致可比口徑納入。'],['agency','純代墊零件 3,000',false,'本例已證明純代墊處理常規，且比較資料採相同排除；不可因金額大就納入。'],['integrated','在地整合零件 1,000',true,'本例 TW 有選配、存貨與整合作業責任，且可靠可比口徑支持納入。']].map(([key,label,expected,why])=>TPLearning.row(label,marked(`[data-cost-item="${key}"]`)?'有勾選':'未勾選',expected?'有勾選':'未勾選',why));
 if(s.kind==='assetScope')return [['rights','可轉讓維保權利',true,'O-02 支持原權利、實際移轉與可得選項。'],['knowhow','可辨識維修 know-how',true,'本例有特定技術與實際授權利用，不是只有一般經驗。'],['title','名片上的新職稱',false,'稱呼本身不是獨立移轉資產。'],['duplicate','已含的相同未來利益再加一次',false,'O-03 的整體估值已排重；再加會重複計價。']].map(([key,label,expected,why])=>TPLearning.row(label,marked(`[data-asset-item="${key}"]`)?'有勾選':'未勾選',expected?'有勾選':'未勾選',why));
 if(s.kind==='verdict')return [TPLearning.numericRow(s.directTax?'本期已確認淨新增稅額':'本案調增所得',val('#story-assessment'),s.amount,s.formula),...s.report.map((text,k)=>TPLearning.row(`報告理由 ${k+1}`,marked(`[data-report-basis="${k}"]`)?'已列入':'未列入','已列入',text)),TPLearning.row('原始文據連結',boardReady(season.current)?'已核對':'尚未完成','已核對','先完成三個待證事實與原始文據的連結，單有正確金額不足以結案。')];return []
}
function shortestQuestion(s,node){const distance=(id,seen=new Set())=>{if(id===s.goal)return 0;if(seen.has(id))return Infinity;const nextSeen=new Set(seen);nextSeen.add(id);return 1+Math.min(...s.nodes[id].choices.map(q=>distance(q.next,nextSeen)))};let best=0;s.nodes[node].choices.forEach((q,k)=>{if(distance(q.next)<distance(s.nodes[node].choices[best].next))best=k});return best}
const oldLearningBody=stepBody;
stepBody=function(e,r,s){if(s.kind!=='crossExamination')return oldLearningBody(e,r,s);const x=lessonFor(e).challenge,d=r.deepDraft||(r.deepDraft={});return `<div class="cross-scene"><div class="cross-scene-art" aria-hidden="true"><span class="cross-person">🕵️</span><span class="cross-paper">▤</span><span class="cross-opponent">${investigationStories[e.id].icon}</span><i></i></div><div class="eyebrow">NEW EVIDENCE · 這份反證可能改變什麼？</div><h3>${x.speaker}帶來另一個解釋。</h3><p>${x.scene}</p></div><div class="hypothesis-pair"><div><small>原假說</small><p>${lessonFor(e).hypotheses[0]}</p></div><div><small>必須排除的另一種解釋</small><p>${lessonFor(e).hypotheses[1]}</p></div></div><label class="cross-question">① 這個新線索出現後，你先採取哪個判斷？<select id="cross-claim"><option value="">先選擇你的查證方向</option>${x.claim.map((v,k)=>`<option value="${k}" ${d.claim===String(k)?'selected':''}>${v}</option>`).join('')}</select></label><label class="cross-question">② 哪一組補核資料最能分辨兩種解釋？<select id="cross-proof"><option value="">選擇待證事項與資料範圍</option>${x.proof.map((v,k)=>`<option value="${k}" ${d.proof===String(k)?'selected':''}>${v}</option>`).join('')}</select></label><button class="primary" id="cross-check">提交補核策略，打開原始資料 →</button>`};
const beforeLearningScene=openCampaignStep;
openCampaignStep=function(){beforeLearningScene();const e=seasonEpisode(),r=seasonRecord(),s=currentStep(),step=r.step,l=lessonFor(e);if(r.complete)return;
 $('.story-play')?.insertAdjacentHTML('afterbegin',`<details class="inquiry-lens" ${step===0?'open':''}><summary>🔎 這一步在查什麼？</summary><p><b>TP 是什麼：</b>檢查關係人交易的價格、報酬與條件，是否貼近可比較獨立企業的常規安排。</p><p><b>本案受控交易：</b>${l.transaction}</p><p><b>現在要完成：</b>${s.title}</p><button class="text-button" id="open-case-learning">打開本案段落與查核方法 →</button></details>`);$('#open-case-learning').onclick=()=>showLearningRules(season.current,true);$('#story-source').onclick=()=>showLearningRules(season.current,true);
 $('.story-casebook')?.insertAdjacentHTML('beforeend','<div class="learning-grade-note">教學練習可立即看詳解、不計分。結案後另有一份交卷評量（總分 100 分；80 分合格、90 分特優）。手動追問、筆記等自由文字不評分。</div>');
 if(s.kind==='crossExamination'){const x=l.challenge;for(const key of ['claim','proof'])$('#cross-'+key).onchange=()=>{r.deepDraft??={};r.deepDraft[key]=$('#cross-'+key).value;saveSeason()};$('#cross-check').onclick=()=>{const a=$('#cross-claim').value,b=$('#cross-proof').value,rows=[TPLearning.row('新線索的初步判斷',a===''?'未作答':x.claim[+a],x.claim[x.correct],x.why),TPLearning.row('補核資料與待證問題',b===''?'未作答':x.proof[+b],x.proof[x.proofCorrect],`${x.why} 正確資料要能區分兩種假說，不只重複取得同一形式文件。`)];r.deepDraft={claim:a,proof:b};if(rows.every(v=>v.ok)){addFile(r,x.file);r.deepAudit={file:x.file,at:learningDate(),claim:x.claim[x.correct],proof:x.proof[x.proofCorrect]};markSolved(e,r,s)}else showFeedback(false,'請依逐項解析修正補核策略；原始資料會在策略成立後解鎖。');appendExplanation(e,s,rows,r,step)};
 }else if(s.kind==='talk'){const d=dialogueState(r,step,s),node=d.node,best=s.nodes[node].choices.length?shortestQuestion(s,node):null;document.querySelectorAll('[data-dialogue-choice]').forEach(button=>{const action=button.onclick,k=+button.dataset.dialogueChoice,q=s.nodes[node].choices[k],recommended=s.nodes[node].choices[best];button.onclick=()=>{const row={label:'這次問話與較可靠追問',actual:q.text,expected:recommended.text,ok:k===best,why:`${k===best?'這個問法較能直接帶到可核對的事實。':'這個問法容易過早採認或省略條件；先用較直接的問題把事實問清楚。'} 對方的回答：${s.nodes[q.next].text}${k===best?' '+s.insight:''}`};action();appendExplanation(e,s,[row],r,step)}});
 }else{const selectors={inspect:'[data-story-choice]',document:'[data-story-clause]',request:'[data-story-request]',puzzle:'#check-story-puzzle',sequence:'#check-story-sequence',costBase:'#check-cost-basket',profitSplit:'#check-split-board',assetScope:'#check-asset-scope',verdict:'#submit-story-assessment'};document.querySelectorAll(selectors[s.kind]||'__none').forEach(button=>{const action=button.onclick;if(s.kind==='verdict')button.textContent='完成查核主張，進入交卷評量 →';button.onclick=()=>{const rows=practiceRows(e,r,s,button);action();if(s.kind==='verdict'&&r.complete){r.practiceLog??=[];r.practiceLog.push({kind:s.kind,label:s.label,step,rows,at:learningDate()});saveSeason();showCaseExam(season.current);return}appendExplanation(e,s,rows,r,step)}})}
 const saved=r.learningFeedback?.[step];if(saved&&!$('#case-feedback .learning-feedback')){const next=$('#next-story-step'),html=explanationHTML(e,s,saved.rows);if(next)next.insertAdjacentHTML('beforebegin',html);else $('#case-feedback').insertAdjacentHTML('beforeend',html)}
};
const beforeLearningBoard=showInvestigationBoard;
showInvestigationBoard=function(i=season.current){beforeLearningBoard(i);const e=episodes[i],r=seasonRecord(i),button=$('#verify-board');if(r.complete)return;const action=button.onclick;button.onclick=()=>{const cfg=investigationStories[e.id],b=boardState(r),rows=cfg.links.map((v,k)=>TPLearning.row(v[0],b.links[k]||'尚未連接',`${v[1]} · ${getFile(e,v[1]).title}`,`${v[2]} 正確連結 ${v[1]} 的原文：${getFile(e,v[1]).lines.join('；')}`)).map((row,k)=>({...row,ok:b.links[k]===cfg.links[k][1]}));action();$('#board-feedback').innerHTML=explanationHTML(e,{kind:'puzzle',label:'推理板',insight:'每份文據只支持相應事實；再將各條證據與反證合併，才能形成有理由的結論。'},rows);r.practiceLog??=[];r.practiceLog.push({kind:'board',label:'推理板',rows,at:learningDate()});saveSeason()}};
function showLearningRules(i,back=false){const e=episodes[i],l=lessonFor(e),domestic=e.authority.includes('臺灣');openModal('查核依據與規範意旨 · '+e.title,`<div class="eyebrow">FACTS → RULES → REASONS</div><h2>不是背一個段號，而是用它問出正確問題。</h2><div class="learning-definition"><b>本案查核對象與受控交易</b><p>${l.transaction}</p><p>FAR：功能、資產、風險。DEMPE：開發、提升、維護、保護、利用。這些分析用來辨識真正的貢獻，仍須再選可靠方法衡量報酬。</p></div><h3>兩個都要認真檢驗的假說</h3><ol>${l.hypotheses.map(v=>`<li>${v}</li>`).join('')}</ol>${ruleCards([...l.refs,...l.quiz.flatMap(q=>q.refs)])}<h3>套進這個案件，為何如此判斷？</h3>${l.reasoning.map(p=>`<p class="learning-prose">${p}</p>`).join('')}<div class="domestic-frame"><b>${domestic?'臺灣例示的法源與程序':'本案為外國側或雙邊範圍的教學假設'}</b><p>${domestic?'所得稅法第 43 條之 1 為常規調整法源；查核準則第 4–9 條之 2 提供交易、可比較性、風險及無形資產分析框架。調閱與核定另依第 22、33 條及其他適用規定；本例仍須區分報核、核定與救濟。':'不以臺灣法規當作該外國案件的核定法源；應另查適用年度、當地法令與協定。本例的 20% 並非外國法定稅率。'}</p><a href="https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=G0340003&flno=43-1" target="_blank" rel="noopener">所得稅法第 43 條之 1 ↗</a> · <a href="https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=G0340019" target="_blank" rel="noopener">TP 查核準則 ↗</a></div><p class="learning-footnote">段落座標固定採 OECD TPG 2022；並非宣稱已涵蓋後續全部更新或 Amount B。本季虛構案例不替代真實方法分析、核定或法律意見。來源核對：2026-10-29。</p><button class="primary" id="rules-learning-back">${back?'回到目前調查現場':'回到結案紀錄'} →</button>`);$('#rules-learning-back').onclick=()=>back?openCampaignStep():showSeasonEnding(i)}
function examRecord(i){const r=seasonRecord(i);r.assessments??=[];return r}
function examNumberField(q,k,d){const hint=q.hint?`<p class="exam-base-hint">${safe(q.hint)}</p>`:'';return `${hint}<input class="exam-number" data-exam-question="${k}" inputmode="decimal" value="${safe(d.answers[k]??'')}" placeholder="依本案資料計算">`}
function showCaseExam(i){const e=episodes[i],r=examRecord(i);if(!r.complete){toast('先完成本案查證與主張，再進入獨立評量。');return}const l=lessonFor(e),d=r.examDraft||(r.examDraft={answers:{},name:'',startedAt:learningDate()});openModal('交卷評量 · '+e.title,`<div class="exam-hero"><div class="exam-cast" aria-hidden="true">🕵️ <span>▤</span> 👩</div><div><div class="eyebrow">THE FINAL CASE CONFERENCE</div><h2>最後一次，請用自己的判斷回答。</h2><p>阿芬與周衡把案卷交還給你。${l.quiz.length} 題，總分 100 分；80 分合格、90 分以上特優。這份評量交卷後才公布答案，教學練習不扣分。</p></div></div><label class="exam-name">證書姓名／暱稱<input id="exam-learner" maxlength="40" value="${safe(d.name)}" placeholder="未填則使用「島嶼學習者」"></label><div class="exam-question-list">${l.quiz.map((q,k)=>`<fieldset class="exam-question"><legend><span>${String(k+1).padStart(2,'0')}</span> ${safe(q.prompt)}</legend><small>${(100/l.quiz.length).toFixed(2)} 分 · ${q.type==='number'?'請填數值；本案金額單位為萬元':'選出最有依據的答案'}</small>${q.type==='choice'?q.options.map((v,j)=>`<label><input type="radio" name="exam-q-${k}" data-exam-question="${k}" value="${j}" ${String(d.answers[k])===String(j)?'checked':''}><b>${String.fromCharCode(65+j)}</b><span>${safe(v)}</span></label>`).join(''):examNumberField(q,k,d)}</fieldset>`).join('')}</div><div class="exam-submit-bar"><span id="exam-completion"></span><small>未作答視為該題 0 分。提交後保存本次答案及成績；重新評量會建立新紀錄。</small><button class="primary" id="submit-case-exam">正式交卷，產生整案報告 →</button></div><button class="text-button" id="exam-save-back">暫存作答，回到結案紀錄</button>`);
 const status=()=>{$('#exam-completion').textContent=`已答 ${l.quiz.filter((_,k)=>String(d.answers[k]??'').trim()!=='').length} / ${l.quiz.length} 題`};document.querySelectorAll('[data-exam-question]').forEach(el=>{const update=()=>{if(el.type==='radio'&&!el.checked)return;d.answers[el.dataset.examQuestion]=el.value;saveSeason();status()};el.oninput=update;el.onchange=update});$('#exam-learner').oninput=()=>{d.name=$('#exam-learner').value;saveSeason()};status();let submitted=false;$('#submit-case-exam').onclick=()=>{if(submitted)return;submitted=true;const a=TPLearning.makeAttempt(l.quiz,d.answers,d.name,new Date().toISOString());a.id=`TP-${e.id}-${Date.now().toString(36).toUpperCase()}`;r.assessments.push(a);r.examDraft=null;saveSeason();showCaseReport(i,r.assessments.length-1)};$('#exam-save-back').onclick=()=>showSeasonEnding(i);saveSeason()}
function assessmentLabel(a){return !a?'尚未交卷':a.grade==='distinction'?'特優':a.grade==='pass'?'合格':'再接再厲'}
function assessmentReview(e,a){const l=lessonFor(e);return l.quiz.map((q,k)=>{const row=a.rows[k],actual=a.answers[k],display=q.type==='choice'?(q.options[+actual]&&actual!==''?`${String.fromCharCode(65+Number(actual))} · ${q.options[+actual]}`:'未作答'):(String(actual??'').trim()||'未作答'),correct=q.type==='choice'?`${String.fromCharCode(65+q.correct)} · ${q.options[q.correct]}`:`${q.correct.toLocaleString()} 萬元`,specific=q.type==='choice'&&actual!==''&&q.reasons[+actual]?q.reasons[+actual]:q.why;return `<article class="report-answer ${row.correct?'answer-right':'answer-wrong'}"><h4>${row.correct?'✓':'✕'} 第 ${k+1} 題 · ${Math.round(row.points*10)/10} / ${Math.round(1000/l.quiz.length)/10} 分</h4><p><b>題目：</b>${q.prompt}</p><dl><dt>你的作答</dt><dd>${safe(display)}</dd><dt>正確答案</dt><dd>${safe(correct)}</dd><dt>判讀理由</dt><dd>${safe(specific)} ${safe(q.why)}</dd><dt>證據座標</dt><dd>${q.file} · ${safe(getFile(e,q.file)?.title||'本案工作表')}</dd></dl>${ruleCards(q.refs)}${row.correct?'':`<button class="text-button" data-review-question="${k}">回頭複習這個爭點 →</button>`}</article>`}).join('')}
function caseReportHTML(i,a){const e=episodes[i],r=seasonRecord(i),l=lessonFor(e),v=e.steps.at(-1),tax=v.directTax?v.amount:TPCampaign.tax(v.taxBase,v.amount),performed=s=>s.kind==='crossExamination'?!!r.deepAudit:r.solved.includes(e.steps.indexOf(s));return `<article class="case-learning-report"><div class="report-cover"><div class="eyebrow">晶島物語 · TP 查核學習報告</div><h2>${e.title}</h2><p>${e.year} · ${e.target}</p><div class="report-score ${a?.grade||'ungraded'}"><b>${a?a.score:'—'}<small>${a?' / 100':' 尚未評量'}</small></b><span>${assessmentLabel(a)}</span></div><p>${a?`學習者：${safe(a.name)} · 第 ${r.assessments.indexOf(a)+1} 次交卷 · ${safe(new Date(a.submittedAt).toLocaleString('zh-TW',{timeZone:'Asia/Taipei',hour12:false}))}`:'這是已完成的案件紀錄；尚無新制交卷成績，不自動頒證。'}</p>${a?`<small>紀錄編號 ${a.id}</small>`:''}</div><h3>一、整案背景與交易範圍</h3>${e.opening.map(p=>`<p>${p}</p>`).join('')}<div class="report-key-fact"><b>受控交易：</b>${l.transaction}<br><b>核心爭點：</b>${e.question}<br><b>本案概念：</b>${e.concept}</div><h3>二、查核假說與反證</h3><table><thead><tr><th>要驗證的假說</th><th>不能省略的另一解釋</th></tr></thead><tbody><tr>${l.hypotheses.map(p=>`<td>${p}</td>`).join('')}</tr></tbody></table><h3>三、實際查核過程</h3><ol class="report-timeline">${e.steps.map(s=>`<li><b>${performed(s)?'✓ 已完成':'○ 未記錄本步'} · ${s.label}</b><p>${s.title}</p><small>${performed(s)?s.insight:'本紀錄可能來自舊版；不將未執行的新補核當成已查得。'}</small></li>`).join('')}</ol><p>教學作答留存 ${r.practiceLog?.length||0} 次；其中含不完整或需修正項目 ${r.practiceLog?.filter(x=>x.rows.some(v=>!v.ok)).length||0} 次。這些是學習歷程，不直接作為獨立評量分數。</p><h3>四、已取得文據與訪談</h3><table><thead><tr><th>文據</th><th>內容與待證事實</th></tr></thead><tbody>${r.files.map(id=>{const f=getFile(e,id);return f?`<tr><td><b>${id}</b><br>${f.title}<br><small>${f.issuer}</small></td><td>${f.lines.map(p=>`<p>${p}</p>`).join('')}</td></tr>`:''}).join('')}</tbody></table>${Object.entries(r.dialogues).map(([k,d])=>`<details class="report-transcript"><summary>${e.steps[k]?.speaker||'受訪人'} · ${e.steps[k]?.label||'訪談'}完整筆錄</summary>${d.history.map(h=>`<p><b>${safe(h.speaker)}：</b>${safe(h.text)}</p>`).join('')}</details>`).join('')}<h3>五、查核依據、規範意旨及適用理由</h3>${ruleCards([...l.refs,...l.quiz.flatMap(q=>q.refs)])}${l.reasoning.map(p=>`<p>${p}</p>`).join('')}<div class="domestic-frame"><b>法源與適用範圍</b><p>${e.authority.includes('臺灣')?'臺灣例示以所得稅法第 43 條之 1 及 TP 查核準則為常規調整分析框架；仍須依法完成報核、核定、納稅人陳述及救濟等適用程序。':'本案是外國側或雙邊概念模擬；適用當地法令與協定須另行確認，不以臺灣程序替代。'}</p><p>OECD TPG 是分析指引；本報告沒有完成真實核定。金額、可靠方法結果與文件均為明列的虛構教學假設。</p><a href="https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=G0340003&flno=43-1">所得稅法第 43 條之 1</a> · <a href="https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=G0340019">TP 查核準則</a></div><h3>六、調整計算與稅額橋接</h3><div class="report-formula">${v.formula}</div><table><thead><tr><th>計算項目</th><th>金額（萬元）</th><th>計算理由</th></tr></thead><tbody>${l.worked.map(q=>`<tr><td>${q.prompt}</td><td>${q.correct.toLocaleString()}</td><td>${q.why}</td></tr>`).join('')}</tbody></table><p>本案僅列有資料支持的交易調整；不推算未提供的全公司所得及稅額。</p><h3>七、結論、範圍與待追蹤</h3><p>${v.closing}</p><p>${v.insight}</p><p>玩家手記：${safe(r.board?.notes||r.notes||'未填寫。')}</p><h3>八、交卷成績與逐題詳解</h3>${a?`<p>本次 ${a.correct} / ${a.total} 題正確，${a.score} 分。${a.grade==='retry'?'再接再厲：可依錯題自選複習、再測或直接選擇其他案例；本次紀錄保留。':'已達學習證書門檻。'} 評分為每題 ${Math.round(1000/l.quiz.length)/10} 分；80 分合格，90 分特優，未答 0 分。</p>${assessmentReview(e,a)}`:'<p>尚未交卷。舊版結案不會被當成新制考試通過。</p>'}<footer>晶島物語自主學習紀錄 · 非 OECD、國稅局或其他機關認證 · 依據核對 2026-10-29</footer></article>`}
function showCaseReport(i,attemptIndex){const e=episodes[i],r=examRecord(i),n=attemptIndex??r.assessments.length-1,a=r.assessments[n];openModal('整案報告與成績 · '+e.title,`${caseReportHTML(i,a)}<div class="report-actions"><button class="primary" onclick="showSeasonJournal()">自由選擇其他案例 →</button><button class="primary" id="download-case-report">下載整案報告 HTML</button><button class="choice" id="print-case-report">列印／另存 PDF</button>${TPLearning.canCertify(a)?'<button class="choice" id="open-case-certificate">領取學習證書 →</button>':''}<button class="choice" id="exam-from-report">${a?'重新評量':'開始交卷評量'} →</button><button class="text-button" id="report-back-ending">回到結案紀錄</button></div>${r.assessments.length>1?`<div class="attempt-history"><label>歷次交卷<select id="report-attempt">${r.assessments.map((v,k)=>`<option value="${k}" ${k===n?'selected':''}>第 ${k+1} 次 · ${v.score} 分 · ${assessmentLabel(v)}</option>`).join('')}</select></label></div>`:''}`);
 wireLearningDownload('download-case-report',`tp-${e.id}-report.html`,caseReportHTML(i,a));$('#print-case-report').onclick=()=>window.print();if($('#open-case-certificate'))$('#open-case-certificate').onclick=()=>showCaseCertificate(i,n);$('#exam-from-report').onclick=()=>{r.examDraft=null;saveSeason();showCaseExam(i)};$('#report-back-ending').onclick=()=>showSeasonEnding(i);document.querySelectorAll('[data-review-question]').forEach(b=>b.onclick=()=>showQuestionReview(i,+b.dataset.reviewQuestion,n));if($('#report-attempt'))$('#report-attempt').onchange=()=>showCaseReport(i,+$('#report-attempt').value)}
function showQuestionReview(i,k,n){const e=episodes[i],q=lessonFor(e).quiz[k],a=seasonRecord(i).assessments[n];openModal(`錯題複習 · 第 ${k+1} 題`,`${assessmentReview(e,{...a,rows:a.rows.map((row,j)=>({...row,correct:j===k?row.correct:true}))}).split('<article').filter(x=>x.includes(`第 ${k+1} 題`)).map(x=>'<article'+x).join('')}<h3>回到原始資料</h3>${documentCard(getFile(e,q.file))}<button class="primary" id="review-report-return">回到本次整案報告 →</button>`);$('#review-report-return').onclick=()=>showCaseReport(i,n);document.querySelectorAll('[data-review-question]').forEach(b=>b.remove())}
function certificateHTML(e,a){const special=a.grade==='distinction';return `<article class="learning-certificate ${special?'certificate-distinction':''}"><div class="certificate-border"><div class="certificate-top">✿ 晶島物語 · TRANSFER PRICING ISLANDS</div><div class="eyebrow">CERTIFICATE OF LEARNING</div><h2>TP 案件學習證書</h2><p>茲證明</p><h3>${safe(a.name)}</h3><p>完成「${e.title}」案件之自主學習與交卷評量</p><div class="certificate-score">${a.score}<small> / 100 分</small></div><p>本次 ${a.correct} / ${a.total} 題正確 · ${special?'90 分以上，評定特優':'達 80 分合格門檻'}</p><div class="certificate-stamp"><b>${special?'特優':'合格'}</b><small>晶島物語<br>學習評量</small></div><div class="certificate-skills">辨認受控交易 · 查證功能與風險 · 回應反證<br>運用 OECD TPG 閱讀座標 · 看懂本案調整與稅額</div><div class="certificate-meta"><span>交卷日期 ${safe(new Date(a.submittedAt).toLocaleDateString('zh-TW',{timeZone:'Asia/Taipei'}))}</span><span>${a.id}</span></div><p class="certificate-disclaimer">本證書僅為本網站未監考、自主練習之學習紀錄；不代表 OECD、國稅局、會計師資格或任何政府機關認證，亦未驗證身分。</p></div></article>`}
function showCaseCertificate(i,n){const e=episodes[i],a=seasonRecord(i).assessments?.[n];if(!TPLearning.canCertify(a)){toast('本次尚未達 80 分，先回頭複習再評量。');return}openModal('學習證書 · '+e.title,`${certificateHTML(e,a)}<div class="report-actions"><button class="primary" id="download-certificate">下載證書 HTML</button><button class="choice" id="print-certificate">列印／另存 PDF</button><button class="text-button" id="certificate-report">回到本次成績報告</button></div>`);wireLearningDownload('download-certificate',`tp-${e.id}-certificate.html`,certificateHTML(e,a));$('#print-certificate').onclick=()=>window.print();$('#certificate-report').onclick=()=>showCaseReport(i,n)}
const exportLearningCSS=`body{background:#faf8ee;color:#304e43;font:15px/1.9 system-ui,"Noto Sans TC",sans-serif;max-width:1000px;margin:35px auto;padding:25px}h2{font-size:30px}h3{margin-top:32px}table{width:100%;border-collapse:collapse}td,th{border:1px solid #cdd7c1;padding:13px;text-align:left;vertical-align:top}th{background:#e9efdc}td p{margin:3px 0}.report-cover{background:#e7eedc;padding:30px;border-radius:12px}.report-score b{font-size:42px}.report-score span{margin-left:25px}.report-key-fact,.report-formula,.domestic-frame{padding:20px;background:#edf0e1;margin:20px 0}.answer-analysis,.report-answer{border:1px solid #cbd8bf;padding:20px;margin:18px 0;border-left:5px solid #7b9d68}.answer-wrong{border-left-color:#b87d5b;background:#f6ecdc}dt{font-weight:bold;color:#70846a}dd{margin:5px 0 15px}.learning-rule{padding:15px;border:1px solid #d8e0ca;margin:10px 0}a{color:#3c7665}footer{margin-top:35px;font-size:11px;border-top:1px solid #ddd;padding-top:20px}.learning-certificate{text-align:center;border:3px solid #99ac82;padding:12px;background:#fffdf2;position:relative}.certificate-border{border:1px solid #c1cda9;padding:50px 45px;position:relative}.certificate-top{letter-spacing:2px;font-size:12px}.eyebrow{letter-spacing:2px;font-size:10px;margin:20px 0}.learning-certificate h2{font-size:36px;letter-spacing:5px}.learning-certificate h3{font-size:31px;letter-spacing:3px}.certificate-score{font-size:55px}.certificate-score small{font-size:15px}.certificate-stamp{border:4px double #628669;color:#628669;border-radius:50%;width:115px;height:115px;display:flex;flex-direction:column;justify-content:center;position:absolute;right:35px;top:240px;transform:rotate(-12deg)}.certificate-stamp b{font-size:28px}.certificate-stamp small{font-size:10px;line-height:1.4}.certificate-distinction .certificate-stamp{color:#ad5b45;border-color:#ad5b45}.certificate-skills{margin:28px 0;color:#728363}.certificate-meta{display:flex;justify-content:space-between;font-size:11px;margin-top:40px}.certificate-disclaimer{font-size:10px;color:#8a927d;margin:28px 0 0}.report-answer button{display:none}@media print{body{margin:0;padding:0}.report-actions{display:none}details{display:block}details> :not(summary){display:block!important}.learning-certificate{break-inside:avoid}h3{break-after:avoid}tr{break-inside:avoid}}`;
const learningDownloadURLs=[];
function wireLearningDownload(id,name,html){const blob=new Blob([`<!DOCTYPE html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${safe(name)}</title><style>${exportLearningCSS}</style><body>${html}</body></html>`],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob),old=document.getElementById(id),link=document.createElement('a');link.id=id;link.className=old.className+' learning-download';link.textContent=old.textContent;link.href=url;link.download=name;old.replaceWith(link);learningDownloadURLs.push(url);if(learningDownloadURLs.length>20)URL.revokeObjectURL(learningDownloadURLs.shift())}

const beforeLearningEnding=showSeasonEnding;
showSeasonEnding=function(i){beforeLearningEnding(i);const r=examRecord(i);if(!r.complete)return;const a=r.assessments.at(-1),passed=r.assessments.some(TPLearning.canCertify);$('#modal-content').insertAdjacentHTML('afterbegin',`<div class="ending-assessment ${a?.grade||'ungraded'}"><div><small>案件交卷與學習評量</small><b>${a?`${a.score} 分 · ${assessmentLabel(a)}`:'本案查核完成，尚未交卷評量'}</b><p>${a?.grade==='retry'?'成績已保存。可自選複習、重新評量，或直接選擇其他案例。':`${lessonFor(episodes[i]).quiz.length} 題共 100 分；80 分合格，90 分以上特優。`}</p></div><button class="primary" id="ending-case-exam">${r.examDraft?'繼續未交卷評量':a?'重新評量':'開始交卷評量'} →</button><button class="choice" id="ending-case-report">整案報告與歷次成績</button></div>`);const pages=document.querySelector('.paper-pages');if(pages){const banner=document.querySelector('.ending-assessment');if(banner)pages.prepend(banner)}
$('#ending-case-exam').onclick=()=>showCaseExam(i);$('#ending-case-report').onclick=()=>showCaseReport(i);$('#modal-content').insertAdjacentHTML('beforeend','<button class="primary" id="choose-any-case">自由選擇下一個案例 →</button>');$('#choose-any-case').onclick=showSeasonJournal;$('#ending-story-sources').onclick=()=>showLearningRules(i,false)};
// Retain old saves; no past completion becomes an exam result or certificate.
for(const [i,r] of Object.entries(season.records)){if(r.complete)r.step=episodes[+i].steps.length-1;}saveSeason();
const formerFeedback=feedbackHTML;
feedbackHTML=function(){return formerFeedback().replace('這個推論還接不上','請看逐項詳解與查核依據')};

renderSeason();
